import React,{useState,useEffect,useSyncExternalStore,useRef} from 'react';
import {motion,AnimatePresence,MotionConfig} from 'motion/react';
import {LayoutDashboard,Clapperboard,Radio,BookOpen,Users,Sparkles,Settings,ChevronDown,ArrowUpRight,Plus,Play,Pause,Square,Volume2,VolumeX,Check,CheckCircle2,ChevronRight,ArrowRight,ArrowLeft,ArrowUp,ArrowDown,Copy,Trash2,Save,Eye,Camera,Monitor,Mic,Music,WandSparkles,Gift,CalendarDays,Search,MoreHorizontal,Menu,X,Download,ExternalLink,Info,ShieldCheck,Link,RefreshCw,AlertCircle,Headphones,MessageCircle,KeyRound,SlidersHorizontal,Heart,CheckCheck,Clock,Layers,FileText,Send,UserPlus,RotateCcw,ShoppingBag} from 'lucide-react';
import CharacterProfile from './CharacterProfile.jsx';
import {StudioEngine,formatDate,productionName,jsonFetch} from './engine.js';
